"""Split executed csimdjson Cython wrapper and vendored simdjson C++ lines; export Parsarium source lines."""
import json
from pathlib import Path

root = Path('/coverage')
raw = json.loads((root / 'native.json').read_text())
prefix = '/work/pysimdjson-source/simdjson/'
# Generated by Cython from csimdjson.pyx, plus the binding's own C++ helpers.
WRAPPER = {prefix + 'csimdjson.cpp', prefix + 'util.cpp', prefix + 'util.h', prefix + 'ondemand.h'}
UNDERLYING = {prefix + 'simdjson.cpp', prefix + 'simdjson.h'}
# Amalgamated simdjson.cpp sections: arm64.cpp and fallback.cpp kernels.
ARM64 = range(14137, 21856)
FALLBACK = range(74530, 79830)
files = []
for item in raw['data'][0]['files']:
    filename = item['filename']
    if not filename.startswith(prefix):
        continue
    if filename not in WRAPPER | UNDERLYING:
        raise SystemExit(f'unexpected source {filename}')
    lines = sorted({line for line, column, count, has_count, region_entry, *_ in item['segments']
                    if has_count and region_entry and count > 0})
    if lines:
        files.append({'filename': filename, 'summary': {'lines': {'covered': len(lines)}},
                      'executed_lines': lines})
by_name = {item['filename']: item['executed_lines'] for item in files}
for required in ('csimdjson.cpp', 'simdjson.cpp', 'simdjson.h'):
    if not by_name.get(prefix + required):
        raise SystemExit(f'{required} had no executed source regions')
kernel = by_name[prefix + 'simdjson.cpp']
arm64 = sum(line in ARM64 for line in kernel)
fallback = sum(line in FALLBACK for line in kernel)
if not arm64 or fallback:
    raise SystemExit(f'expected the arm64 kernel only: arm64={arm64} fallback={fallback}')
observed = json.loads((root / 'observed.json').read_text())
coverage = {'data': [{'files': files}]}
wrapper = [item for item in files if item['filename'] in WRAPPER]
underlying = [item for item in files if item['filename'] in UNDERLYING]
summary = {'control_pass': True, 'output': observed, 'parser_source_files': len(files),
           'parser_source_lines_covered': sum(len(item['executed_lines']) for item in files),
           'wrapper_source_files': len(wrapper),
           'wrapper_source_lines_covered': sum(len(item['executed_lines']) for item in wrapper),
           'underlying_source_files': len(underlying),
           'underlying_source_lines_covered': sum(len(item['executed_lines']) for item in underlying),
           'underlying_arm64_kernel_lines_covered': arm64,
           'underlying_fallback_kernel_lines_covered': fallback,
           'coverage': '/coverage/coverage.json'}
(root / 'coverage.json').write_text(json.dumps(coverage, indent=2) + '\n')
(root / 'summary.json').write_text(json.dumps(summary, indent=2, ensure_ascii=False) + '\n')
print(json.dumps(summary, ensure_ascii=False))
